from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    X = int(input[1])
    D = int(input[2])

    if D == 0:
        if X == 0:
            print(1)
        else:
            print(N + 1)
        return

    residue_intervals = defaultdict(list)

    for k in range(0, N+1):
        if k == 0:
            min_Q = 0
            max_Q = 0
        else:
            min_Q = k * (k - 1) // 2
            max_Q = k * (2 * N - k - 1) // 2

        A = X * k + D * min_Q
        B = X * k + D * max_Q

        r = (X * k) % D

        start = min(A, B)
        end = max(A, B)

        residue_intervals[r].append( (start, end) )

    total = 0
    for r in residue_intervals:
        intervals = residue_intervals[r]
        intervals.sort()
        merged = []
        for interval in intervals:
            if not merged:
                merged.append(interval)
            else:
                last_start, last_end = merged[-1]
                curr_start, curr_end = interval
                if curr_start <= last_end:
                    new_start = last_start
                    new_end = max(last_end, curr_end)
                    merged[-1] = (new_start, new_end)
                else:
                    merged.append( (curr_start, curr_end) )
        for s, e in merged:
            count = (e - s) // abs(D) + 1
            total += count

    print(total)

