            for b in [0, 1]:
                if b > current_k_bit:
                    continue
                new_tight = tight and (b == current_k_bit)
                if b == 0:
                    contribution = cnt[bit] * (1 << bit)
                else:
                    contribution = (N - cnt[bit]) * (1 << bit)
                res = contribution + dfs(bit - 1, new_tight)
                if res > max_sum:
                    max_sum = res
        else:
            for b in [0, 1]:
                if b == 0:
                    contribution = cnt[bit] * (1 << bit)
                else:
                    contribution = (N - cnt[bit]) * (1 << bit)
                res = contribution + dfs(bit - 1, False)
                if res > max_sum:
