from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx]); idx +=1
    M_a = int(input[idx]); idx +=1
    M_b = int(input[idx]); idx +=1

    packages = []
    for _ in range(N):
        a = int(input[idx]); idx +=1
        b = int(input[idx]); idx +=1
        c = int(input[idx]); idx +=1
        d = a * M_b - b * M_a
        packages.append( (d, c) )

    n1 = N // 2
    n2 = N - n1

    def generate_subsets(packages):
        k = len(packages)
        min_total = defaultdict(lambda: float('inf'))
        min_non_empty = defaultdict(lambda: float('inf'))
        for mask in range(0, 1 << k):
            sum_d = 0
            cost = 0
            is_empty = True
            for i in range(k):
                if mask & (1 << i):
                    is_empty = False
                    sum_d += packages[i][0]
                    cost += packages[i][1]
            if is_empty:
                if sum_d == 0:
                    if cost < min_total[sum_d]:
                        min_total[sum_d] = cost
            else:
                if cost < min_total[sum_d]:
                    min_total[sum_d] = cost
                if cost < min_non_empty[sum_d]:
                    min_non_empty[sum_d] = cost
        return min_total, min_non_empty

    first_half = packages[:n1]
    second_half = packages[n1:]

    min_total1, min_non_empty1 = generate_subsets(first_half)
    min_total2, min_non_empty2 = generate_subsets(second_half)

    answer = float('inf')

    for sum1 in min_total1:
        sum2 = -sum1
        if sum2 in min_total2:
            if sum1 == 0 and sum2 == 0:
                possible_costs = []
                if min_non_empty1[sum1] != float('inf'):
                    possible_costs.append(min_non_empty1[sum1] + min_total2[sum2])
                if min_non_empty2[sum2] != float('inf'):
                    possible_costs.append(min_total1[sum1] + min_non_empty2[sum2])
                if min_non_empty1[sum1] != float('inf') and min_non_empty2[sum2] != float('inf'):
                    possible_costs.append(min_non_empty1[sum1] + min_non_empty2[sum2])
                if possible_costs:
                    current_min = min(possible_costs)
                    if current_min < answer:
                        answer = current_min
            else:
                current_cost = min_total1[sum1] + min_total2[sum2]
                if current_cost < answer:
                    answer = current_cost

